import java.util.*;
import java.util.stream.Collectors;
public final class LabelStream {
    private LabelStream() {}
    public static List<String> cleanLabels(List<String> labels) {
        return labels.stream().map(String::trim).filter(label -> label.length() >= 4)
                .sorted().collect(Collectors.toList());
    }
    public static Optional<String> firstLabel(List<String> labels) {
        return cleanLabels(labels).stream().findFirst();
    }
}
